    inv_float_n: DATA_TYPE
    inv_float_n = 1.0 / float_n

    inv_float_n_minus_1: DATA_TYPE
    inv_float_n_minus_1 = 1.0 / (float_n - 1.0)

    # 1) Compute column means.
    # Initialize means.
    for j in seq(0, m):
        mean[j] = 0.0

    # Accumulate sums over rows using row-major traversal for good cache behavior.
    for i in seq(0, n):
        for j in seq(0, m):
            mean[j] += data[i, j]

    # Normalize means by N.
    for j in seq(0, m):
        mean[j] = mean[j] * inv_float_n

    # 2) Center the data matrix: subtract the mean from each column.
    for i in seq(0, n):
        for j in seq(0, m):
            data[i, j] = data[i, j] - mean[j]

    # 3) Initialize the full covariance matrix to zero.
    # This keeps the semantics simple and makes later accumulation a pure reduction.
    for i in seq(0, m):
        for j in seq(0, m):
            cov[i, j] = 0.0

    # 4) Accumulate the upper triangular covariance (including the diagonal).
    # Each cov[i, j] with j >= i accumulates sum_k data[k, i] * data[k, j].
    for i in seq(0, m):
        for j in seq(i, m):
            for k in seq(0, n):
