EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# High-level covariance kernel.
#
# The algorithm follows the standard three-stage structure:
#   1. Compute column means.
#   2. Center the data matrix by subtracting the mean from each column.
#   3. Compute the sample covariance matrix:
#        cov = (1 / (float_n - 1)) * data^T * data
#
# Compared to the naive PolyBench order, the loops are written to:
#   - Traverse `data` row-major (i.e., contiguous in memory) whenever possible.
#   - Accumulate the covariance by iterating over rows first (good data locality).
#   - Only compute the upper-triangular part of `cov` and then mirror it.

@proc
def kernel_covariance(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    # ---- 1. Compute column means -----------------------------------------
    # Zero means.
    for j_mean_init in seq(0, m):
        mean[j_mean_init] = 0.0

    # Accumulate sums over rows. Loop over rows first so `data[i, j]`
    # is accessed in row-major order (contiguous in `j`).
    for i_mean_acc in seq(0, n):
        for j_mean_acc in seq(0, m):
            mean[j_mean_acc] += data[i_mean_acc, j_mean_acc]

    # Normalize by the number of rows.
    for j_mean_norm in seq(0, m):
        mean[j_mean_norm] = mean[j_mean_norm] / float_n

    # ---- 2. Center the data matrix ---------------------------------------
    # For each row, subtract the precomputed column mean. This loop writes
    # each row of `data` exactly once and is a good candidate for parallelism.
    for i_center in seq(0, n):
        for j_center in seq(0, m):
            data[i_center, j_center] = data[i_center, j_center] - mean[j_center]

    # ---- 3. Compute covariance matrix ------------------------------------

    # 3a. Initialize only the upper-triangular part of `cov` to zero.
    for i_cov_init in seq(0, m):
        for j_cov_init in seq(i_cov_init, m):
            cov[i_cov_init, j_cov_init] = 0.0

    # 3b. Accumulate outer products of centered rows.
    #
    # For each row k (a centered sample vector x_k of length m), we add
    #   x_k[i] * x_k[j]  for all  0 <= i <= j < m
    # into `cov[i, j]`. This matches X^T X over n rows but restricted
    # to the upper triangle.
    for k_sample in seq(0, n):
        for i_cov in seq(0, m):
            # Cache the i-th entry of this row so we don't reload it
            # inside the inner j-loop.
            tmp_i: DATA_TYPE
            tmp_i = data[k_sample, i_cov]
            for j_cov in seq(i_cov, m):
                cov[i_cov, j_cov] += tmp_i * data[k_sample, j_cov]

    # 3c. Scale by 1 / (float_n - 1) to obtain the unbiased sample covariance
    #     and mirror the upper triangle into the lower triangle.
    scale: DATA_TYPE
    scale = 1.0 / (float_n - 1.0)

    for i_scale in seq(0, m):
        # Diagonal element.
        cov[i_scale, i_scale] = cov[i_scale, i_scale] * scale
        # Off-diagonal elements; enforce symmetry explicitly.
        for j_scale in seq(i_scale + 1, m):
            cov[i_scale, j_scale] = cov[i_scale, j_scale] * scale
            cov[j_scale, i_scale] = cov[i_scale, j_scale]

# --------------------------------------------------------------------------
# Scheduling: restructure loops for parallelism while preserving semantics.
# --------------------------------------------------------------------------

p = kernel_covariance

# 1) Parallelize centering over rows. Each iteration of `i_center` touches a
#    distinct row of `data` and only reads `mean`, so iterations are
#    independent and can safely run in parallel.
p = parallelize_loop(p, "i_center")

# 2) Parallelize the per-row covariance accumulation over `i_cov`.
#    For a fixed (k_sample), each `i_cov` iteration writes to a distinct
#    stripe of the upper triangle:
#       {(i_cov, j) | j in [i_cov, m)}
#    Hence different `i_cov` iterations do not write the same `cov[i, j]`,
#    and the loop is safe to parallelize.
p = parallelize_loop(p, "i_cov")

# 3) Parallelize scaling and symmetrization over rows of `cov`.
#    Each `i_scale` iteration writes:
#      - the diagonal element (i_scale, i_scale)
#      - the i_scale-th row above the diagonal: (i_scale, j), (j, i_scale).
#    No `(i, j)` pair is written by more than one `i_scale` iteration, so
#    this loop is also independent across iterations.
p = parallelize_loop(p, "i_scale")

# 4) Apply a simplification pass to clean up any algebraic redundancies
#    introduced during scheduling.
p = simplify(p)

# Expose the scheduled version under the original name so that the generated
# C function remains `kernel_covariance`, matching this driver.
kernel_covariance = p
