from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline covariance kernel.
# The algorithm matches PolyBench/C covariance semantics:
#   1) compute column means,
#   2) center the data matrix,
#   3) compute the covariance matrix and symmetrize it.
@proc
def kernel_covariance(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    # 1. Initialize column means to zero.
    # Separated from the accumulation loop so that we can
    # later reorder the accumulation for better locality without
    # changing the exact order of additions for each mean[j].
    for j in seq(0, m):
        mean[j] = 0.0

    # 2. Accumulate column sums in a row-major order.
    # This traverses 'data' with the inner loop over 'j',
    # which is contiguous in memory for DATA_TYPE[n, m].
    for i in seq(0, n):
        for j in seq(0, m):
            mean[j] += data[i, j]

    # 3. Normalize means by the number of rows.
    for j in seq(0, m):
        mean[j] = mean[j] / float_n

    # 4. Center the data by subtracting the mean from each column.
    # This is also row-major: inner loop over 'j'.
    for i in seq(0, n):
        for j in seq(0, m):
            data[i, j] = data[i, j] - mean[j]

    # 5. Compute the covariance matrix in the original
    # (i, j, k) loop order used by PolyBench.
    # We exploit symmetry by only computing the upper triangle
    # and mirroring it into the lower triangle.
    for i in seq(0, m):
        for j in seq(i, m):
            cov[i, j] = 0.0
            for k in seq(0, n):
