# Scheduling: locality, blocking, and parallelization
# ------------------------------------------------------------

# Tunable blocking factors. These are compile-time constants and can
# be adjusted to better match a particular machine's cache hierarchy.
J_TILE = 64   # tile size for column loops in mean accumulation
I_TILE = 32   # tile size for outer i-loop in covariance
K_TILE = 64   # tile size for inner k-loop (reduction) in covariance


p = kernel_covariance

