# embarrassingly parallel.
j_init = p.find_loop("j #0")   # initialization mean[j] = 0
p = parallelize_loop(p, j_init)

j_scale = p.find_loop("j #1")  # normalization mean[j] /= float_n
p = parallelize_loop(p, j_scale)

